  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   nr,nc=r+dr,c+dc
   if 0<=nr<h and 0<=nc<w and not free[nr,nc] and g[nr,nc]!=1:
    free[nr,nc]=True;q.append((nr,nc))
 # Preserve every 4-connected 1-component touching the selected open region.
